import React, { useEffect, useState } from "react";

const getMovesetPath = (battleMode) =>
    battleMode === "singles"
        ? "/singles/csv_movesets/"
        : "/doubles/csv_movesets/";

export default function PokemonBuildPanel({
    clickedBuild,
    battleMode,
}) {
    const [buildData, setBuildData] = useState(null);

    const MOVESET_PATH = getMovesetPath(battleMode);

    const normalize = (name) =>
        name
            ?.toLowerCase()
            .replace(/[^a-z0-9\s-]/g, "")
            .trim()
            .replace(/\s+/g, "-");

    const getImageName = (name) =>
        name
            ?.toLowerCase()
            .replace(/[^a-z0-9]/g, "") || "";

    const loadCSV = async (path) => {
        const res = await fetch(path);
        return await res.text();
    };

    const parseCSV = (text) =>
        text
            .trim()
            .split(/\r?\n/)
            .slice(1)
            .map((r) =>
                r.split(/,(?=(?:(?:[^"]*"){2})*[^"]*$)/)
            );

    useEffect(() => {
        if (!clickedBuild || !clickedBuild.sourceFile) {
            setBuildData(null);
            return;
        }

        const loadBuild = async () => {
            const text = await loadCSV(
                MOVESET_PATH + clickedBuild.sourceFile
            );

            const rows = parseCSV(text);

            const pokemonRows = rows.filter(
                (r) =>
                    normalize(r[1]) ===
                    normalize(clickedBuild.pokemon)
            );

            const grouped = {};

            for (let row of pokemonRows) {
                const category = row[2];

                const itemName =
                    category === "Stats"
                        ? row[3]
                        : row[4];

                const usage = row[5];

                if (
                    category === "Stats" &&
                    [
                        "Raw count",
                        "Avg. weight",
                        "Viability Ceiling",
                    ].includes(itemName)
                )
                    continue;

                if (category === "Spreads") continue;

                if (!itemName) continue;

                if (!grouped[category]) {
                    grouped[category] = [];
                }

                grouped[category].push({
                    name: itemName,
                    usage,
                });
            }

            Object.keys(grouped).forEach((cat) => {
                grouped[cat] = grouped[cat]
                    .sort(
                        (a, b) =>
                            Number(b.usage) - Number(a.usage)
                    )
                    .slice(0, 5);
            });

            setBuildData({
                display: clickedBuild.display,
                month: clickedBuild.month,
                data: grouped,
            });
        };

        loadBuild();
    }, [clickedBuild, MOVESET_PATH]);

    if (!buildData) {
        return (
            <div style={{ padding: "10px" }}>
                Click a graph point to view build
            </div>
        );
    }

    return (
        <div
            style={{
                height: "600px",
                overflowY: "auto",
                border: "1px solid #ccc",
                borderRadius: "10px",
                padding: "12px",
                background: "#fafafa",
            }}
        >
            <img
                src={`/pokemon_artwork/${getImageName(buildData.display)}.jpg`}
                alt={buildData.display}
                style={{
                    width: "110px",
                    display: "block",
                    margin: "0 auto 10px",
                    borderRadius: "10px",
                    boxShadow: "0 2px 6px rgba(0,0,0,0.2)",
                }}
            />

            <h3 style={{ textAlign: "center", marginBottom: "10px" }}>
                {buildData.display} — {buildData.month}
            </h3>

            <div style={{ fontSize: "14px" }}>
                {Object.entries(buildData.data).map(
                    ([category, items]) => (
                        <div key={category} style={{ marginBottom: "10px" }}>
                            <strong>{category}</strong>
                            <ul style={{ marginTop: "5px" }}>
                                {items.map((item, idx) => (
                                    <li key={idx}>
                                        {item.name} ({item.usage}%)
                                    </li>
                                ))}
                            </ul>
                        </div>
                    )
                )}
            </div>
        </div>
    );
}
